INSERT INTO `bonk_map_locale` (`id`, `locale`, `name`, `summary`, `description`)
VALUES
  (1, 'zhCN', '西部荒野', '迪菲亚暴徒、豺狼人、鱼人', '被迪菲亚兄弟会占据的农田。艾德温·范克里夫、基尔尼格或斯尼德的伐木机坐镇本阶段。'),
  (2, 'zhCN', '熔火之心', '火焰元素、熔火恶犬、熔火巨人', '黑石山燃烧的心脏。玛格曼达、古雷曼格或迦顿男爵坐镇本阶段，加尔、鲁西弗隆和基赫纳斯紧随其后。'),
  (3, 'zhCN', '贫瘠之地', '野猪人、半人马、土狼', '遍布钢鬃和科卡尔劫掠者的无尽干旱平原。卡尔加·刺肋、暴怒的阿迦赛罗斯或吞噬者穆坦努斯坐镇本阶段。'),
  (4, 'zhCN', '暮色森林', '亡灵、狼人、食人魔', '亡者横行的黑暗森林。缝合怪、摩本特·费尔或伊莉莎坐镇本阶段。'),
  (5, 'zhCN', '祖尔格拉布', '古拉巴什巨魔、蝙蝠、猛虎', '古拉巴什的神庙之城。哈卡、高阶祭司塞卡尔或血领主曼多基尔坐镇本阶段，金度、温诺希斯和玛尔里紧随其后。'),
  (6, 'zhCN', '安其拉废墟', '异种虫群、其拉人、阿努比萨斯', '安其拉残破的大门。无疤者奥斯里安或卡苏姆男爵坐镇本阶段。'),
  (7, 'zhCN', '塔纳利斯', '土狼、食人魔、废土流浪者强盗', '祖尔法拉克周围烈日炙烤的沙丘。加兹瑞拉或乌克兹·沙顶坐镇本阶段。'),
  (8, 'zhCN', '安戈洛环形山', '魔暴龙、迅猛龙、软泥怪', '巨兽统治的原始环形山。暴龙之王摩什或格里什皇后坐镇本阶段。'),
  (9, 'zhCN', '荆棘谷', '丛林巨魔、猛虎、猩猩', '遍布血顶和劈颅巨魔的茂密丛林。莫什奥格领主或甘祖拉恩坐镇本阶段。'),
  (10, 'zhCN', '凄凉之地', '半人马、蝎子、萨特', '半人马部族彼此征战的荒凉大地。瑟莱德丝公主、被诅咒的塞雷布拉斯或洛特格里普坐镇本阶段。'),
  (11, 'zhCN', '荒芜之地', '穴居人、黑铁矮人、雏龙', '奥达曼上方焦灼的峡谷。阿扎达斯、古代的石头看守者或黑曜石哨兵坐镇本阶段。'),
  (12, 'zhCN', '阿拉希高地', '食人魔、枯木巨魔、辛迪加', '被食人魔和亡命之徒占据的连绵高地。弗兹鲁克或纳兹加克王子坐镇本阶段。'),
  (13, 'zhCN', '悲伤沼泽', '鳄鱼、失落者、阿塔莱', '环绕阿塔哈卡神庙的沉陷沼泽。哈卡的化身、预言者迦玛兰或摩弗拉斯坐镇本阶段。'),
  (14, 'zhCN', '燃烧平原', '黑石兽人、黑龙人', '黑石塔下的灰烬与烈焰。索瑞森大帝和达基萨斯将军分别坐镇各个阶段。'),
  (15, 'zhCN', '东瘟疫之地', '天灾、憎恶、瘟疫犬', '斯坦索姆城下的瘟疫中心。瑞文戴尔男爵和巴纳扎尔分别坐镇各个阶段。'),
  (16, 'zhCN', '西瘟疫之地', '血色十字军、食尸鬼、瘟疫野兽', '通灵学院与血色十字军营地之间的田野。黑暗院长加丁、詹迪斯·巴罗夫或瑟尔林·卡斯迪诺夫教授坐镇本阶段。'),
  (17, 'zhCN', '菲拉斯', '豺狼人、食人魔、厄运之槌', '厄运之槌周围的古老森林。戈多克大王和托塞德林王子分别坐镇各个阶段。'),
  (18, 'zhCN', '灼热峡谷', '黑铁矮人、魔像、熔岩蜘蛛', '黑石山脚下熔融的矿渣坑。雷德·黑手和比斯巨兽分别坐镇各个阶段。'),
  (19, 'zhCN', '费伍德森林', '萨特、恶魔、碧火', '恶魔横行的腐化森林。卡扎克和克罗苏斯分别坐镇各个阶段。'),
  (20, 'zhCN', '丹莫罗', '穴居人、霜鬃巨魔、诺莫瑞根', '诺莫瑞根之下冰流湖的冰封湖岸。穴居人和巨魔先行，麦克尼尔·瑟玛普拉格或黑铁大使及其机器随后登场。'),
  (21, 'zhCN', '银松森林', '狼人、腐皮豺狼人、达拉然法师', '一片被阿鲁高的狼人盘踞的黑暗松林。阿鲁高或狼王南杜斯坐镇本阶段。'),
  (22, 'zhCN', '湿地', '鱼人、藓皮豺狼人、龙喉兽人', '龙喉兽人和黑铁矮人占据的沼泽。纳克罗什酋长或邪恶的巴尔加拉斯坐镇本阶段。'),
  (23, 'zhCN', '希利苏斯', '异种虫巢穴、暮光信徒、圣殿骑士', '异种虫巢穴遍布的沙漠，暮光之锤在此召唤元素领主。斯卡德诺克斯王子或卡苏姆男爵坐镇本阶段。'),
  (24, 'zhCN', '洛克莫丹', '穴居人、坑道鼠狗头人、莫格罗什食人魔', '被穴居人和狗头人占据的高地湖泊，山丘中还有食人魔。玛高什或大头目加尔高什坐镇本阶段。'),
  (25, 'zhCN', '黑海岸', '黑木熊怪、灰雾鱼人、纳迦', '漫长而林木茂密的海岸，疯狂的熊怪和纳迦袭击者出没。薇丝普拉女士或辛斯雷尔领主坐镇本阶段。'),
  (26, 'zhCN', '赤脊山', '赤脊山豺狼人、黑石兽人、黑色雏龙', '红色的山丘，豺狼人和黑石氏族在此劫掠农场。萨瑞尔祖恩或加塞尔佐格坐镇本阶段。'),
  (27, 'zhCN', '希尔斯布莱德丘陵', '希尔斯布莱德民兵、泥嘴豺狼人、破鳍鱼人', '希尔斯布莱德民兵据守的农田和丘陵。阿拉加或斯格霍尔坐镇本阶段。'),
  (28, 'zhCN', '千针石林', '加拉克半人马、恐怖图腾牛头人、风蛇', '石柱耸立的峡谷，半人马和恐怖图腾在此争夺。不可战胜的铁眼或阿纳克·恐怖图腾坐镇本阶段。'),
  (29, 'zhCN', '尘泥沼泽', '黑鳍鱼人、血沼迅猛龙、火鬃龙人', '遍布迅猛龙、鱼人和巨龙沼泽龙人的雾气沼泽。莫格穆洛克大王或布雷姆戈坐镇本阶段。'),
  (30, 'zhCN', '冬泉谷', '冬泉熊怪、雪人、霜刃豹、蓝龙人', '雪人、枭兽和冬泉部族栖息的冰封山谷。冬泉酋长或泰比斯蒂亚公主坐镇本阶段。'),
  (31, 'zhCN', '艾萨拉', '恨鳞纳迦、木喉熊怪、赫达琳', '上层精灵的废墟海岸，纳迦和血精灵在此劫掠。鳞须海龟或伊夫卡尔坐镇本阶段。'),
  (32, 'zhCN', '诅咒之地', '巨槌食人魔、魔誓祭司、恶魔', '黑暗之门前的焦土荒原，信徒在此召唤恶魔。吞噬者特雷姆斯或末日守卫指挥官坐镇本阶段。');
